"""Render the text question expansion from its public, reviewed evidence bundle."""
from html import escape as e
import hashlib
import json
from pathlib import Path
from site_navigation import project_tabs,experiment_subtabs

ROOT=Path(__file__).resolve().parents[1];D=ROOT/'research/question-expansion'
def p(s):return '<p>'+e(str(s))+'</p>'
def table(n,title,headers,rows):return '<div class="qe-table"><table><caption>Table '+str(n)+'. '+e(title)+'</caption><thead><tr>'+''.join('<th scope="col">'+e(h)+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+e(str(v))+'</td>' for v in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def question(q):
    evidence=''
    for c in q.get('source_evidence',[]):
        evidence+='<li><code>'+e(c['id'])+'</code> · '+e(c['speaker'])+' · '+f"{c['start']:.2f}–{c['end']:.2f} s"+(p(c['text']) if c.get('text') else '')+'</li>'
    reads=''
    for r in q['readbacks']:
        response=r.get('response') or {}
        reads+='<div class="qe-reader"><strong>'+e(r['condition'].replace('_',' '))+'</strong>'+p(response.get('answer','No complete answer parsed.'))+p('Citations: '+(', '.join(response.get('evidence_ids',[])) or 'none'))+(p('Missing: '+'; '.join(response.get('missing_information',[]))) if response.get('missing_information') else '')+(p('Invalid citations: '+', '.join(r['invalid_evidence_ids'])) if r['invalid_evidence_ids'] else '')+'</div>'
    for r in q.get('span_readbacks',[]):
        response=r.get('response') or {}
        reads+='<div class="qe-reader"><strong>Evidence first · '+e(r['condition'].replace('_',' '))+'</strong>'+p(response.get('answer','No complete answer parsed.'))+p('Exact-span check: '+r['guard_status'])+(p('Flags: '+', '.join(r['span_errors'])) if r['span_errors'] else '')+'</div>'
    review=q['reader_review'];status=q['final_decision']
    return '<article class="card qe-question" id="'+e(q['id'])+'" data-status="'+e(status)+'" data-dataset="'+e(q['dataset_group'])+'" data-origin="'+e(q['origin_group'])+'"><div class="qe-tags"><span class="tag">'+e(status)+'</span><span class="tag blue">'+e(q['origin_group'])+'</span></div><h3>'+e(q['question'])+'</h3>'+p(q['meeting']+' · '+f"{q['at']:.2f} s"+' · requester '+q['requester']+' → separate assistant')+p(q['review']['note'])+'<p><strong>Reviewed reference:</strong> '+e(q['reviewed_reference'])+'</p>'+p('Reader full prefix: '+review['full_prefix']+'. Recent minute: '+review['recent_60s']+'. '+review['note'])+(p(q['timing_revision']) if q.get('timing_revision') else '')+'<details><summary>Evidence and five reader conditions</summary><ul>'+evidence+'</ul>'+(p('Earnings source text is retained locally; source IDs and times identify the original ConEC records.') if q['dataset_group']=='earnings' else '')+reads+'</details></article>'
def main():
    study=json.loads((D/'study.json').read_text());qs=json.loads((D/'questions.json').read_text());lit=json.loads((D/'literature.json').read_text());tools=json.loads((D/'tool-fixtures.json').read_text())
    body='<header class="site-nav"><div class="nav-inner"><a class="brand" href="../index.html">AI2AI Duplex</a>'+project_tabs('experiments','../')+'</div></header><main id="main"><div class="container">'+experiment_subtabs('ami')+'<header class="hero"><span class="eyebrow">Text development study · 26 October 2026</span><h1>Natural questions across more meetings</h1><p class="lede">Four new AMI meetings and two earnings calls, with a Qwen3-30B Instruct reader and explicit checks that a question needs earlier conversation.</p></header>'
    body+='<section class="section" id="findings"><h2>What the expansion shows</h2>'+''.join(p(x) for x in study['findings'])+'<p><a href="ami-questions.html">Earlier one-meeting text pilot</a> · <a href="ami-question-audio.html">Existing three-question audio pilot</a> · <a href="#questions">Inspect this question set</a></p></section>'
    body+='<section class="section" id="pipeline"><h2>From a conversation prefix to a checked question</h2><figure class="qe-flow"><div class="qe-stages">'+''.join('<div><strong>'+e(a)+'</strong>'+p(b)+'</div>' for a,b in [('1 · Past speech','Input: speaker-labelled, timed transcript. Output: completed chunks available before one cutoff.'),('2 · Evidence and requester','Input: past chunks and available role metadata. Output: an earlier fact, a plausible requester and a reason to ask now.'),('3 · Spoken wording','Input: the prefix or a reviewed evidence packet. Output: one short question plus a proposed reference. A separate assistant-authored question tests the same information need.'),('4 · Blinded reading','Input: question, requester and allowed transcript only. Output: the 30B reader’s answer, citations and missing facts, under five context conditions.'),('5 · Source review','Input: wording, actual reader answers and source utterances. Output: retain/reject decisions and corrected references. Fluency and JSON success are insufficient.')])+'</div><figcaption>Figure 1. The text pipeline. Evidence packets are supervised source selection; they do not contain the authored question or its reference answer. This study produces no new TTS or audio injections.</figcaption></figure><p>The reader is <strong>Qwen3-30B-A3B-Instruct-2507</strong>, a non-thinking 30B mixture-of-experts checkpoint. vLLM runs BF16 weights with prefix caching and CUDA graphs, a 49,152-token context and an 8 GiB KV cache. Reader output is capped at 1,536 tokens. The maximum audited reader prompt is '+str(study['largest_reader_input_tokens'])+' tokens.</p><p>The local generator and reader use the same checkpoint. Reading a local draft is therefore a consistency check, not independent model judging. Primary-assistant review is also not a human naturalness rating. The new meetings are development data; prompt/source selection was revised after inspecting drafts, so there is no blind generalisation claim.</p></section>'
    body+=p(study['curation_scope'])
    body+='<section class="section" id="sources"><h2>More conversations, different timing quality</h2>'+table(1,'Source conversations in this expansion. Each request is an independent branch; multiple questions at one cutoff are alternatives.',['Source','Conversation','Speaker information','Timing / media'],study['source_rows'])+'<p>AMI chunks use manual word/speaker annotations and an assumed 0.5-second release delay. For EN2002b, requester perspectives come from past speech because formal roles are absent. The scenario meetings use their assigned design-team roles. No speakers overlap between the four new AMI groups.</p><p>ConEC provides corrected words and automatic alignments. In the two inspected calls, '+str(study['earnings_untimed_words'])+' of '+str(study['earnings_words'])+' words lack complete boundaries. Untimed suffixes wait for a following timed token; the final unanchored suffix is withheld. This convention supports a text-prefix experiment, not a claim of verified audio insertion timing. No earnings audio is downloaded or hosted here.</p><p>Recorded analyst questions address management. Our generated earnings requests are explicitly simulated private asides by an already observed participant to a separate assistant. Complete participant lists and vocabulary harvested from later in a call are excluded from the reader.</p></section>'
    body+='<section class="section" id="quality"><h2>What needed rejection or correction</h2>'+table(2,'First whole-prefix generation pass, before supervised packet selection. Each of eight AMI cutoffs has two prompt styles. These are review dispositions, not an accuracy ranking.',['Disposition','Calls'],study['initial_rows'])+'<p>The first pass invented a docking-station-specific budget and used “D” as a spoken vocative. The packet pass still changed a 50% survey result to 34%. We preserved that raw output and corrected only its reference before considering the question. Another draft supplied “TV only” in its own question; natural confirmation wording can still be a weak test of memory.</p><p>The three result types in EN2002b were repeated within the last minute at the first cutoff. That local question is a rejected history diagnostic. The authored version was moved to the later cutoff before reading. This change is recorded on the question card. A reference’s old citation does not prove that its answer is unavailable in recent speech.</p>'+table(3,'Manual content review of actual reader answers. Candidate variants share information needs; counts are not independent samples or human-rated accuracy.',['Group','Question variants','Full prefix adequate','Recent minute adequate','Retained after review'],study['reader_rows'])+'<p>“Adequate” means the required proposition is correctly recovered without changing its speaker, numerical value or decision status. Partial, unsupported or contradictory answers do not pass. Full-prefix success paired with failure from recent speech is a useful history diagnostic, not proof that a model uses history causally.</p><p>The five reader conditions are full prefix, newest 60 seconds, question only, speaker labels removed, and selected evidence removed. Evidence removal deletes cited chunks; equivalent information can remain elsewhere. Removing labels leaves any naturally spoken names intact. Neither ablation is a perfect removal of all information. Across all '+str(study['reader_calls'])+' calls, '+str(study['invalid_citation_calls'])+' have citations outside their supplied context and '+str(study['truncated_reader_calls'])+' reach the output cap. These mechanical checks remain separate from content review.</p></section>'
    body+='<section class="section" id="questions"><h2>Review the questions and their controls</h2><p>Retained examples are shown first. The initial rejected packet drafts and the unchanged earlier EN2003a questions remain selectable for diagnosis. Proposed references are synthetic labels reviewed against source speech, not recorded ground-truth responses.</p><div class="qe-filters"><label>Decision <select id="status-filter"><option value="retain">Retained</option><option value="all">All</option><option value="reject">Rejected diagnostics</option><option value="legacy">Earlier comparison</option></select></label><label>Dataset <select id="dataset-filter"><option value="all">All</option><option value="ami">AMI</option><option value="earnings">Earnings calls</option></select></label><label>Wording <select id="origin-filter"><option value="all">All</option><option value="authored">Assistant-authored</option><option value="local">Local 30B Instruct</option><option value="legacy">Earlier pilot</option></select></label><output id="question-count" aria-live="polite"></output></div><div class="qe-questions">'+''.join(question(q) for q in qs)+'</div></section>'
    body+='<section class="section" id="documents"><h2>A concrete route to document tools</h2><p>ConEC is the closest immediate match because it pairs the calls with real slides and releases. A local read-only backend implements <code>search_documents(call, time, query)</code> and <code>get_page(call, time, document, page)</code>. It returns page text, a source URL and the PDF hash. Earlier speech must announce the document as available on the company website; this is availability evidence, not an archived upload timestamp.</p>'+table(5,'Two executed scripted retrieval fixtures. Query and page selection were authored, not chosen by a model; an autonomous tool policy is still untested.',['Synthetic request','Retrieved source','Checked result'],[[x['question'],x['source_label'],x['expected']] for x in tools])+'<p>Both intended pages appear in the top three search results. The backend also rejects a search before the availability announcement and a page request from the wrong call. Raw PDF files and full call transcripts remain with the original sources and in the local study data.</p><p>For a tool-policy experiment, pair these with transcript-only reminders and questions whose document is unavailable. Score whether retrieval was needed, whether the correct call/page was opened, and whether units and qualifiers survived. A calculator can follow retrieval when arithmetic is actually required; these two lookups need no fabricated calculation.</p></section>'
    body+='<section class="section" id="datasets"><h2>Which datasets serve which purpose</h2>'+table(6,'Verified primary resources. Corpus descriptions are source reports; the pilot and recommendations are our observations.',['Resource','Use here / next','Limit'],[[x['title'],x['relevance'],x['limit']] for x in lit['papers']])+'<ol>'+''.join('<li><a href="'+e(x['url'])+'">'+e(x['title'])+'</a> — '+e(x['authors'])+', '+str(x['year'])+', '+e(x['venue'])+'.</li>' for x in lit['papers'])+'</ol><p>FinCall-Surprise offers a larger call-plus-slides pool, but full media are external archives and its alignment/speaker coverage has not been audited here. Contextual Earnings-22 supplies short vocabulary-stress clips rather than full conversations. FinQA and TAT-QA help with document reasoning and arithmetic labels, but their questions should not be presented as original spoken call requests.</p></section>'
    body+='<section class="section" id="resources"><h2>Execution and limits</h2>'+table(7,'Actual allocations; jobs ran sequentially. All model weights and KV cache share GPU 0. No S1, TTS or ASR service runs alongside them.',['Job','Stage','GPU count / type / VRAM','GPU role','Allocation'],study['job_rows'])+p('Maximum experiment GPUs active at once: '+str(study['maximum_active_gpus'])+'. Total allocation: '+str(study['gpu_hours'])+' GPU hours. Data preparation, PDF extraction, review and publication run on CPUs (0 GPUs). No experiment job remains active.')+'<p>This establishes a reviewed text development set and a runnable 30B reader. It does not establish a human naturalness score, generalisation to unseen meetings, streaming ASR robustness or autonomous tool use. A useful next trial is a small blind human review, followed by voice-conditioned injection of the strongest AMI questions using the existing audio recipe.</p></section><footer class="section"><p><a href="../research/question-expansion/study.json">Study and content-review counts</a> · <a href="../research/question-expansion/questions.json">Questions, evidence and reader conditions</a> · <a href="../research/question-expansion/initial-review.json">Initial draft review</a> · <a href="../research/question-expansion/literature.json">Dataset digest</a> · <a href="../research/question-expansion/manifest.json">Public file hashes</a></p><p>AMI source: <a href="https://groups.inf.ed.ac.uk/ami/corpus/">AMI Meeting Corpus</a>. Earnings source: <a href="https://github.com/huangruizhe/ConEC">ConEC</a> and <a href="https://github.com/revdotcom/speech-datasets">Rev speech datasets</a>. Questions are synthetic; original source speakers did not record these assistant requests.</p></footer></div></main>'
    span_section='<section class="section" id="span-reader"><h2>Evidence-first reader follow-up</h2>'+''.join(p(x) for x in study['span_findings'])+table(4,'Four full-prefix qualification probes after inspecting reader failures. No broader follow-up ran because qualification failed.',['Question','Original content review','Evidence-first result','Exact-span check','Qualification'],study['span_rows'])+'<p>The bounded retry ran only full-prefix qualification probes ('+str(study['span_calls'])+' model calls). Separate CPU checks of an empty-context guard cover '+str(study['empty_gate_cases'])+' empty-context cases without model inference; these are backend checks, not reader accuracy. Unknown IDs and non-verbatim quotations quarantine an answer for review. A correct quotation can still accompany a wrong inference.</p></section>'
    body=body.replace('<section class="section" id="documents">',span_section+'<section class="section" id="documents">')
    css='''.qe-flow{margin:20px 0}.qe-stages{display:grid;gap:10px;grid-template-columns:repeat(auto-fit,minmax(175px,1fr))}.qe-stages>div{border:1px solid var(--border);border-radius:10px;padding:15px;background:var(--surface-2)}.qe-stages p{font-size:.9rem}.qe-flow figcaption{margin-top:12px;color:var(--muted)}.qe-table{overflow:auto;border:1px solid var(--border);border-radius:10px;margin:22px 0}.qe-table table{min-width:740px;table-layout:auto}.qe-questions{display:grid;gap:18px}.qe-question h3{font-size:1.12rem}.qe-question p{overflow-wrap:anywhere}.qe-tags,.qe-filters{display:flex;gap:10px;flex-wrap:wrap;align-items:center}.qe-filters{margin:20px 0}.qe-filters label{display:flex;gap:8px;align-items:center}.qe-filters select{background:var(--surface);color:var(--text);border:1px solid var(--border);border-radius:6px;padding:8px}.qe-reader{margin:12px 0;background:var(--surface-2);padding:12px;border-radius:8px}.qe-reader p{margin:6px 0}details{margin:16px 0}summary{cursor:pointer;color:var(--accent)}[hidden]{display:none!important}'''
    js="""const fields=['status','dataset','origin'];function filter(){let n=0;for(const c of document.querySelectorAll('.qe-question')){c.hidden=!fields.every(f=>{const v=document.getElementById(f+'-filter').value;return v==='all'||c.dataset[f]===v});if(!c.hidden)n++}document.getElementById('question-count').textContent=n+' questions shown'}for(const f of fields)document.getElementById(f+'-filter').addEventListener('change',filter);filter();function reveal(){const c=document.getElementById(location.hash.slice(1));if(c?.classList.contains('qe-question')){for(const f of fields)document.getElementById(f+'-filter').value='all';filter();c.scrollIntoView()}}addEventListener('hashchange',reveal);if(location.hash)reveal();"""
    version=hashlib.sha256((ROOT/'assets/site.css').read_bytes()).hexdigest()[:12]
    page='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="color-scheme" content="light dark"><meta name="description" content="Source-reviewed natural questions across four AMI meetings and two earnings calls, with a blinded Qwen3-30B Instruct reader and concrete PDF retrieval fixtures."><title>More meeting questions · AI2AI Duplex</title><link rel="stylesheet" href="../assets/site.css?v='+version+'"><style>'+css+'</style></head><body><a class="skip-link" href="#main">Skip to question expansion</a>'+body+'<script>'+js+'</script></body></html>\n'
    (ROOT/'experiments/question-expansion.html').write_text(page)
    print('Rendered',len(qs),'question variants')
if __name__=='__main__':main()
